/* ── 100m NL Messieurs Senior (Championnat National 2025) ── */
INSERT INTO nations_ranking (athlete_id, event_id, best_time_ms, points_fina, rank_position, season, created_at)
SELECT 5,  e.id, 50340, 875, 1, '2024-2025', NOW() FROM events e WHERE e.competition_id=1 AND e.swim_style='LIBRE' AND e.distance=100 AND e.gender='MASCULIN' LIMIT 1;
