/* Record national — 100m NL Messieurs Senior */
INSERT INTO records (athlete_id, event_id, competition_id, swim_style, distance, time, temps_ms, temps_display, date, record_date, type, created_at)
SELECT 5, e.id, 1, e.swim_style::VARCHAR, CAST(e.distance AS VARCHAR), (50340/1000)::INT, 50340, '50.34', '2025-03-10', '2025-03-10', 'NATIONAL', NOW()
FROM events e WHERE e.competition_id=1 AND e.swim_style='LIBRE' AND e.distance=100 AND e.gender='MASCULIN' LIMIT 1;
